<script setup lang="ts">import{ref,onMounted}from'vue';import{api}from'../api';const organizations=ref<any[]>([]),organizationId=ref(''),devices=ref<any[]>([]),deviceId=ref(''),features=ref<any[]>([]),data=ref<any>(null),loading=ref(false),saving=ref(false),error=ref('');async function boot(){try{organizations.value=(await api('/tk-api/enterprise/platform/tenants')).tenants;if(organizations.value.length){organizationId.value=String(organizations.value[0].id);await loadDevices()}}catch(e:any){error.value=e.message}}async function loadDevices(){deviceId.value='';features.value=[];const response=await api(`/api/v2/platform/devices?organization_id=${organizationId.value}`);devices.value=response.items||[];if(devices.value.length){deviceId.value=devices.value[0].device_id;await loadFeatures()}}async function loadFeatures(){if(!deviceId.value)return;loading.value=true;error.value='';try{data.value=await api(`/api/v2/platform/devices/${deviceId.value}/features`);features.value=Object.entries(data.value.features).map(([code,value])=>({code,...(value as any)}))}catch(e:any){error.value=e.message}finally{loading.value=false}}async function save(){if(!window.confirm('设备级覆盖优先于企业和套餐配置，保存后该设备会立即刷新。确认继续吗？'))return;saving.value=true;try{await api(`/api/v2/platform/devices/${deviceId.value}/features`,{method:'PUT',body:JSON.stringify({items:features.value.map(x=>({feature_code:x.code,enabled:x.enabled,reason:'平台设备级覆盖'}))})});await loadFeatures()}catch(e:any){error.value=e.message}finally{saving.value=false}}onMounted(boot);</script>
<template><section class="panel"><header class="panel-head"><div><span class="eyebrow">DEVICE OVERRIDES</span><h2>平台设备功能</h2><p>仅用于单台测试设备灰度或临时关闭异常能力。</p></div><button class="primary" :disabled="saving||!deviceId" @click="save">{{saving?'正在保存…':'保存设备覆盖'}}</button></header><div class="toolbar"><select v-model="organizationId" @change="loadDevices"><option value="" disabled>选择企业</option><option v-for="x in organizations" :value="String(x.id)">{{x.name}}</option></select><select v-model="deviceId" @change="loadFeatures"><option value="" disabled>选择设备</option><option v-for="x in devices" :value="x.device_id">{{x.display_name}}</option></select><span v-if="data" class="quota">设备配置版本 {{data.config_version}}</span></div><div v-if="loading" class="state-inline">正在获取设备功能……</div><div v-else-if="error" class="state-inline error"><b>暂时无法加载设备功能</b><span>{{error}}</span><button @click="loadFeatures">立即重试</button></div><div v-else-if="!deviceId" class="empty-state"><b>当前企业还没有设备</b><p>设备加入企业后，可在这里设置设备级灰度。</p></div><div v-else class="entitlement-list"><label v-for="x in features" :key="x.code"><input v-model="x.enabled" type="checkbox"><span><b>{{x.name}}</b><small>{{x.code}} · {{x.source}}</small></span><em>{{x.enabled?'已启用':'已关闭'}}</em></label></div></section></template>
